-- ---------------------------------------------------------------------------
-- E2 unified AI domain (continued): PostgreSQL DDL for the AI-domain tables that
-- only ever shipped MySQL DDL, plus one table that had no DDL at all.
--
-- Generated by scripts/db/mysql-to-postgres.py from the legacy MySQL install script
-- (services/platform/docs/script/sql/ruoyi-ai.sql) and the E0 table map
-- (mydocs/platform-embedded/03-table-map.json); the ai_model_config block is
-- hand-written because no source SQL exists for it.
--
-- Conversion conventions (also documented in the generator header):
--   * MySQL inline COMMENT becomes COMMENT ON COLUMN
--   * AUTO_INCREMENT becomes GENERATED BY DEFAULT AS IDENTITY
--   * ON UPDATE CURRENT_TIMESTAMP is dropped: PostgreSQL has no column-level
--     equivalent and the application fills update_time in its meta object handler
--   * FULLTEXT indexes are dropped (no direct equivalent) and were reported at
--     generation time so the omission is deliberate
--   * UNSIGNED is dropped
--
-- NOT VERIFIED against a live PostgreSQL yet; see the E2 spec risk E2-R2.
-- ---------------------------------------------------------------------------

-- ===== chat_model -> ai_model =====
CREATE TABLE IF NOT EXISTS platform.ai_model (
    "id" bigint NOT NULL,
    "category" varchar(20) DEFAULT NULL,
    "model_name" varchar(50) DEFAULT NULL,
    "provider_code" varchar(20) DEFAULT NULL,
    "model_describe" varchar(255) DEFAULT NULL,
    "model_dimension" integer DEFAULT NULL,
    "model_show" char(1) DEFAULT NULL,
    "api_host" varchar(255) DEFAULT NULL,
    "api_key" varchar(255) DEFAULT NULL,
    "create_dept" bigint DEFAULT NULL,
    "create_by" bigint DEFAULT NULL,
    "create_time" timestamp DEFAULT NULL,
    "update_by" bigint DEFAULT NULL,
    "update_time" timestamp DEFAULT NULL,
    "remark" varchar(500) DEFAULT NULL,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
);
COMMENT ON TABLE platform.ai_model IS '模型管理';
COMMENT ON COLUMN platform.ai_model."id" IS '主键';
COMMENT ON COLUMN platform.ai_model."category" IS '模型分类';
COMMENT ON COLUMN platform.ai_model."model_name" IS '模型名称';
COMMENT ON COLUMN platform.ai_model."provider_code" IS '模型供应商';
COMMENT ON COLUMN platform.ai_model."model_describe" IS '模型描述';
COMMENT ON COLUMN platform.ai_model."model_dimension" IS '模型维度';
COMMENT ON COLUMN platform.ai_model."model_show" IS '是否显示';
COMMENT ON COLUMN platform.ai_model."api_host" IS '请求地址';
COMMENT ON COLUMN platform.ai_model."api_key" IS '密钥';
COMMENT ON COLUMN platform.ai_model."create_dept" IS '创建部门';
COMMENT ON COLUMN platform.ai_model."create_by" IS '创建者';
COMMENT ON COLUMN platform.ai_model."create_time" IS '创建时间';
COMMENT ON COLUMN platform.ai_model."update_by" IS '更新者';
COMMENT ON COLUMN platform.ai_model."update_time" IS '更新时间';
COMMENT ON COLUMN platform.ai_model."remark" IS '备注';
COMMENT ON COLUMN platform.ai_model."tenant_id" IS '租户Id';

