-- ===== knowledge_info -> ai_knowledge_base =====
CREATE TABLE IF NOT EXISTS platform.ai_knowledge_base (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "user_id" bigint NOT NULL DEFAULT 0,
    "name" varchar(50) NOT NULL,
    "share" smallint DEFAULT NULL,
    "description" varchar(1000) DEFAULT NULL,
    "separator" varchar(255) DEFAULT NULL,
    "overlap_char" integer DEFAULT NULL,
    "retrieve_limit" integer DEFAULT NULL,
    "similarity_threshold" double precision DEFAULT 0.5,
    "text_block_size" integer DEFAULT NULL,
    "vector_model" varchar(50) DEFAULT NULL,
    "embedding_model" varchar(50) DEFAULT NULL,
    "create_dept" varchar(255) DEFAULT NULL,
    "create_by" varchar(50) DEFAULT NULL,
    "create_time" timestamp DEFAULT NULL,
    "update_by" bigint DEFAULT NULL,
    "update_time" timestamp DEFAULT NULL,
    "remark" varchar(500) DEFAULT NULL,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    "enable_rerank" smallint DEFAULT 0,
    "rerank_score_threshold" double precision DEFAULT NULL,
    "rerank_top_n" integer DEFAULT NULL,
    "rerank_model" varchar(100) DEFAULT NULL,
    "enable_hybrid" smallint DEFAULT 0,
    "hybrid_alpha" double precision DEFAULT 0.5,
    "system_prompt" text,
    PRIMARY KEY ("id")
);
