-- ===== chat_config -> ai_model_config =====
-- 该表在任何已交付脚本里都没有 DDL：ruoyi-ai 的 MySQL 安装脚本、update/ 增量与 platform 的
-- PostgreSQL 迁移中都没有 CREATE TABLE chat_config，但实体/服务/控制器都存在
-- （org.ruoyi.system.domain.ChatConfig extends TenantEntity），说明建表语句只存在于作者的开发库。
-- 因此本表按 Java 实体字段补齐（含 TenantEntity 的 tenant_id 与 BaseEntity 的审计列），不做 SQL 转换。
-- E0 表映射把本表来源标注为 java-entity 以保持可追溯。
--
-- tenant_id 类型是 E2 待决项 E2-D1：platform 的 sys_tenant.tenant_id 为 varchar(20)，
-- 而 AI 域既有表（含本文件其余表）用 bigint。统一租户表示需要真实 ID 映射；
-- 在决定之前这里沿用 AI 域的 bigint，不做静默类型强转。
CREATE TABLE IF NOT EXISTS platform.ai_model_config (
    "id" bigint NOT NULL,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    "category" varchar(64) DEFAULT NULL,
    "config_name" varchar(128) NOT NULL,
    "config_value" varchar(1024) DEFAULT NULL,
    "config_dict" varchar(512) DEFAULT NULL,
    "remark" varchar(500) DEFAULT NULL,
    "version" bigint DEFAULT NULL,
    "del_flag" char(1) NOT NULL DEFAULT '0',
    "update_ip" varchar(64) DEFAULT NULL,
    "create_dept" bigint DEFAULT NULL,
    "create_by" bigint DEFAULT NULL,
    "create_time" timestamp DEFAULT NULL,
    "update_by" bigint DEFAULT NULL,
    "update_time" timestamp DEFAULT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT uk_model_config_tenant UNIQUE (tenant_id, category, config_name, del_flag)
);
COMMENT ON TABLE platform.ai_model_config IS '模型/系统配置（按实体补齐，原仓库无 DDL）';
COMMENT ON COLUMN platform.ai_model_config."tenant_id" IS '租户Id（E2-D1 待统一类型）';
CREATE INDEX IF NOT EXISTS idx_model_config_tenant ON platform.ai_model_config (tenant_id);

